'use client';

import { useState, useEffect } from 'react';
import { VoiceAppWithChat } from '@/components/voice-agent/voice-app-with-chat';
import { Loader2, AlertCircle } from 'lucide-react';

export default function VoiceAgentChatPage() {
  const [token, setToken] = useState<string>('');
  const [serverUrl, setServerUrl] = useState<string>('');
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string>('');

  useEffect(() => {
    fetchConnectionDetails();
  }, []);

  const fetchConnectionDetails = async () => {
    try {
      setLoading(true);
      setError('');
      
      const authToken = localStorage.getItem('access_token');
      if (!authToken) {
        setError('Not authenticated. Please login first.');
        setLoading(false);
        return;
      }

      const response = await fetch('/api/connection-details', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${authToken}`,
        },
        body: JSON.stringify({ room_config: {} }),
      });

      if (!response.ok) {
        const errorText = await response.text();
        throw new Error(`Failed to get connection details: ${errorText}`);
      }

      const data = await response.json();
      
      if (!data.serverUrl || !data.participantToken) {
        throw new Error('Invalid response: missing serverUrl or participantToken');
      }

      setServerUrl(data.serverUrl);
      setToken(data.participantToken);
    } catch (err: any) {
      console.error('Connection error:', err);
      setError(err.message || 'Failed to connect to voice agent');
    } finally {
      setLoading(false);
    }
  };

  const handleDisconnect = () => {
    // Reconnect on disconnect
    fetchConnectionDetails();
  };

  if (loading) {
    return (
      <div className="h-screen w-full bg-background flex items-center justify-center">
        <div className="text-center space-y-4">
          <Loader2 className="w-12 h-12 animate-spin mx-auto text-primary" />
          <div>
            <h3 className="text-lg font-semibold">Connecting to Voice Agent...</h3>
            <p className="text-sm text-muted-foreground mt-2">
              Setting up your LiveKit session
            </p>
          </div>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="h-screen w-full bg-background flex items-center justify-center">
        <div className="max-w-md text-center space-y-4">
          <AlertCircle className="w-12 h-12 mx-auto text-red-500" />
          <div>
            <h3 className="text-lg font-semibold">Connection Failed</h3>
            <p className="text-sm text-muted-foreground mt-2">{error}</p>
          </div>
          <button
            onClick={fetchConnectionDetails}
            className="px-6 py-2 bg-primary text-white rounded-lg hover:bg-primary/90 transition-colors"
          >
            Retry Connection
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="h-screen w-full bg-background">
      <VoiceAppWithChat 
        token={token}
        serverUrl={serverUrl}
        onDisconnect={handleDisconnect}
        agentName="Parker_165"
      />
    </div>
  );
}
